/**
 * Live terminal rendering of session events for `run` / `eval`.
 * Writes to a caller-provided sink (usually stderr) so stdout can stay JSON.
 */
export function createStreamProgress(options) {
    const write = options?.write ?? ((s) => process.stderr.write(s));
    const color = options?.color ?? (process.stderr.isTTY && process.env.NO_COLOR === undefined);
    const c = makePalette(color);
    let assistantOpen = false;
    let thinkingShown = false;
    const turnStartedAt = new Map();
    const toolStartedAt = new Map();
    let turnClock = 0;
    const closeAssistant = () => {
        if (assistantOpen) {
            write("\n");
            assistantOpen = false;
        }
    };
    const elapsed = (since) => `${Date.now() - since}ms`;
    return {
        onEvent(event) {
            switch (event.type) {
                case "session.started": {
                    write(c.dim(`session ${event.sessionId}\n`));
                    break;
                }
                case "agent.bound": {
                    closeAssistant();
                    write(`  ${c.cyan("agent")} ${c.bold(event.data.sdkAgentId)}\n`);
                    if (event.data.url !== undefined) {
                        write(`  ${c.dim(event.data.url)}\n`);
                    }
                    break;
                }
                case "turn.queued": {
                    write(c.dim(`  turn ${event.turnId ?? "?"} queued (position ${event.data.position}, max ${event.data.maxRunningTurns} running)\n`));
                    break;
                }
                case "turn.started": {
                    turnClock = Date.now();
                    if (event.turnId !== undefined) {
                        turnStartedAt.set(event.turnId, turnClock);
                    }
                    write(c.dim(`  turn ${event.turnId ?? "?"} started\n`));
                    break;
                }
                case "message.received": {
                    thinkingShown = false;
                    write(`${c.bold("› user")}  ${truncate(event.data.text, 120)}\n`);
                    break;
                }
                case "reasoning.appended": {
                    if (event.data.parentCallId !== undefined) {
                        break;
                    }
                    if (!thinkingShown) {
                        thinkingShown = true;
                        write(c.dim("  · thinking…\n"));
                    }
                    break;
                }
                case "message.appended": {
                    // Nested subagent deltas stay inside the task chip/indent, not
                    // the parent agent stream.
                    if (event.data.parentCallId !== undefined) {
                        break;
                    }
                    if (!assistantOpen) {
                        write(`${c.green("‹ agent")}  `);
                        assistantOpen = true;
                    }
                    write(event.data.delta);
                    break;
                }
                case "message.completed": {
                    if (event.data.parentCallId !== undefined) {
                        break;
                    }
                    closeAssistant();
                    break;
                }
                case "step.started": {
                    write(c.dim(`  · step ${event.data.stepId}\n`));
                    break;
                }
                case "step.completed": {
                    write(c.dim(`  · step ${event.data.stepId} (${event.data.durationMs}ms)\n`));
                    break;
                }
                case "actions.requested": {
                    closeAssistant();
                    const now = Date.now();
                    for (const call of event.data.calls) {
                        if (call.toolName === "task" && call.parentCallId === undefined) {
                            // Covered by subagent.called; avoid a duplicate bare `task` line.
                            continue;
                        }
                        toolStartedAt.set(call.callId, now);
                        const indent = call.parentCallId !== undefined || event.data.parentCallId !== undefined
                            ? "    "
                            : "  ";
                        write(`${indent}${c.magenta("⚙")} ${c.bold(call.toolName)}${c.dim(formatArgs(call.args))}\n`);
                    }
                    break;
                }
                case "action.approval_requested": {
                    closeAssistant();
                    write(`    ${c.yellow("⏸")} ${c.bold(event.data.toolName)} ${c.dim("awaiting human approval")}\n`);
                    break;
                }
                case "action.approval_resolved": {
                    const mark = event.data.decision === "approve" ? c.green("✓") : c.red("✗");
                    write(`    ${mark} ${c.bold(event.data.toolName)} ${c.dim(event.data.decision === "approve" ? "approved" : "denied")}\n`);
                    break;
                }
                case "action.auth_requested": {
                    closeAssistant();
                    write(`    ${c.yellow("⏸")} ${c.bold(event.data.connection)} ${c.dim("awaiting MCP authorization")}\n`);
                    break;
                }
                case "action.auth_resolved": {
                    const mark = event.data.decision === "approve" ? c.green("✓") : c.red("✗");
                    write(`    ${mark} ${c.bold(event.data.connection)} ${c.dim(event.data.decision === "approve" ? "connected" : "denied")}\n`);
                    break;
                }
                case "action.tool_retry": {
                    write(`    ${c.yellow("↻")} ${c.bold(event.data.toolName)} ${c.dim(`again as try ${event.data.attempt} (${event.data.reason})`)}\n`);
                    break;
                }
                case "action.result": {
                    if (event.data.toolName === "task" && event.data.parentCallId === undefined) {
                        break;
                    }
                    const started = toolStartedAt.get(event.data.callId);
                    toolStartedAt.delete(event.data.callId);
                    const dur = started === undefined ? "" : c.dim(` ${elapsed(started)}`);
                    const mark = event.data.isError ? c.red("✗") : c.magenta("✓");
                    const indent = event.data.parentCallId !== undefined ? "      " : "    ";
                    write(`${indent}${mark} ${c.bold(event.data.toolName)}${dur} ${c.dim(truncate(stringify(event.data.output), 90))}\n`);
                    break;
                }
                case "subagent.called": {
                    closeAssistant();
                    const detail = event.data.description ? ` — ${truncate(event.data.description, 60)}` : "";
                    write(`  ${c.magenta("task")} ${c.bold(event.data.name ?? "subagent")}${c.dim(detail)}\n`);
                    break;
                }
                case "subagent.completed": {
                    write(`  ${c.magenta("✓")} ${c.bold(event.data.name ?? "subagent")} ${c.dim("done")}\n`);
                    break;
                }
                case "turn.completed": {
                    closeAssistant();
                    const usage = event.data.usage;
                    const tokens = usage ? ` · in ${usage.inputTokens} out ${usage.outputTokens} tok` : "";
                    const turnStart = event.turnId !== undefined ? turnStartedAt.get(event.turnId) : turnClock || undefined;
                    const wall = turnStart !== undefined && turnStart > 0
                        ? ` · ${elapsed(turnStart)} wall`
                        : turnClock > 0
                            ? ` · ${elapsed(turnClock)} wall`
                            : "";
                    write(c.dim(`  ─ turn done${tokens}${wall}\n`));
                    if (event.turnId !== undefined) {
                        turnStartedAt.delete(event.turnId);
                    }
                    break;
                }
                case "turn.failed": {
                    closeAssistant();
                    write(`${c.red("  ✗ turn failed")} ${event.data.message}\n`);
                    break;
                }
                case "session.failed": {
                    closeAssistant();
                    write(`${c.red("  ✗ session failed")} ${event.data.message}\n`);
                    break;
                }
                case "session.waiting":
                case "session.completed": {
                    closeAssistant();
                    break;
                }
                default:
                    break;
            }
        },
        close: closeAssistant,
    };
}
const IDENTITY = (s) => s;
function makePalette(enabled) {
    if (!enabled) {
        return {
            dim: IDENTITY,
            bold: IDENTITY,
            cyan: IDENTITY,
            green: IDENTITY,
            red: IDENTITY,
            magenta: IDENTITY,
            yellow: IDENTITY,
        };
    }
    const wrap = (code) => (s) => `\u001b[${code}m${s}\u001b[0m`;
    return {
        dim: wrap("2"),
        bold: wrap("1"),
        cyan: wrap("36"),
        green: wrap("32"),
        red: wrap("31"),
        magenta: wrap("35"),
        yellow: wrap("33"),
    };
}
function stringify(value) {
    if (value === undefined || value === null) {
        return "(no output)";
    }
    return typeof value === "string" ? value : JSON.stringify(value);
}
function formatArgs(args) {
    if (args === undefined || args === null) {
        return "";
    }
    const text = typeof args === "string" ? args : JSON.stringify(args);
    return text === "{}" ? "" : `(${truncate(text, 80)})`;
}
function truncate(text, max) {
    const oneLine = text.replace(/\s+/g, " ").trim();
    return oneLine.length > max ? `${oneLine.slice(0, max - 1)}…` : oneLine;
}
